    "goldSql": "SELECT ROUND(AVG(day_total), 2) AS average_saturday FROM (SELECT CAST(\"date\" AS DATE) AS day, SUM(\"net_sales\") AS day_total FROM \"data\" WHERE DAYNAME(CAST(\"date\" AS DATE)) = 'Saturday' GROUP BY 1) t",
